import { useEffect, useMemo, useState } from 'react';
import { CityPicker } from './components/CityPicker';
import { ModeToggle, SettingsPanel } from './components/Controls';
import { DesktopGrid } from './components/DesktopGrid';
import { MobileGrid } from './components/MobileGrid';
import { OverlapSummary } from './components/OverlapSummary';
import { CITY_CATALOG, findCity, type City } from './lib/cities';
import { loadState, saveState, type AppState, type Mode } from './lib/storage';
import {
  buildSchedule,
  computeOverlaps,
  getUtcOffsetMinutes,
  type Settings,
} from './lib/time';
import { useMediaQuery, useNow } from './hooks';
import type { CityRow } from './types';

export default function App() {
  const [state, setState] = useState<AppState>(loadState);
  const now = useNow();
  const isDesktop = useMediaQuery('(min-width: 768px)');

  useEffect(() => saveState(state), [state]);

  const cities = useMemo(
    () => state.cities.map(findCity).filter((c): c is City => c !== undefined),
    [state.cities],
  );

  const rows = useMemo<CityRow[]>(() => {
    const offsets = cities.map((c) => getUtcOffsetMinutes(c.timezone, now));
    const schedule = buildSchedule(offsets, state.settings);
    const overlaps = computeOverlaps(schedule, state.mode);
    return cities.map((city, i) => ({
      city,
      offset: offsets[i],
      slots: schedule[i],
      overlap: overlaps[i],
    }));
  }, [cities, now, state.settings, state.mode]);

  const available = useMemo(
    () => CITY_CATALOG.filter((c) => !state.cities.includes(c.id)),
    [state.cities],
  );

  const addCity = (id: string) =>
    setState((s) => (s.cities.includes(id) ? s : { ...s, cities: [...s.cities, id] }));

  const removeCity = (id: string) =>
    setState((s) => ({ ...s, cities: s.cities.filter((c) => c !== id) }));

  const promoteCity = (id: string) =>
    setState((s) =>
      s.cities[0] === id ? s : { ...s, cities: [id, ...s.cities.filter((c) => c !== id)] },
    );

  const updateSettings = (patch: Partial<Settings>) =>
    setState((s) => ({ ...s, settings: { ...s.settings, ...patch } }));

  const setMode = (mode: Mode) => setState((s) => ({ ...s, mode }));

  const format = state.settings.format;

  return (
    <div className="app">
      <header className="app-header">
        <div>
          <h1>Claude Haiku 5.5</h1>
          <p className="tagline">Find when your people are awake at the same time.</p>
        </div>
        <ModeToggle mode={state.mode} onChange={setMode} />
      </header>

      <section className="toolbar">
        <CityPicker available={available} onAdd={addCity} />
        <SettingsPanel settings={state.settings} onChange={updateSettings} />
      </section>

      {rows.length === 0 ? (
        <p className="empty">No cities yet. Add one above to start comparing.</p>
      ) : (
        <>
          <OverlapSummary rows={rows} mode={state.mode} format={format} />

          {isDesktop ? (
            <DesktopGrid
              rows={rows}
              format={format}
              highlightHeader={state.mode === 'meeting'}
              onPromote={promoteCity}
              onRemove={removeCity}
            />
          ) : (
            <MobileGrid rows={rows} format={format} onPromote={promoteCity} onRemove={removeCity} />
          )}
        </>
      )}

      <footer className="hint">Green cells = everyone awake</footer>
    </div>
  );
}

args.streamContent:
:root {
  --bg: #0a0f1d;
  --surface: #111a2e;
  --surface-2: #162340;
  --border: #22304f;
  --text: #e7ecf7;
  --text-muted: #8493b3;
  --accent: #34d399;
  --accent-strong: #10b981;
  --overlap-text: #04251a;
  --awake-bg: #18243f;
  --awake-text: #b9c5e0;
  --asleep-bg: #0c1325;
  --asleep-text: #3a4766;
  --warn: #fbbf24;
  --radius: 10px;
  color-scheme: dark;
  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, sans-serif;
  line-height: 1.4;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }

html, body, #root { margin: 0; min-height: 100%; }

body {
  background:
    radial-gradient(1200px 500px at 10% -10%, rgba(52, 211, 153, 0.08), transparent 60%),
    radial-gradient(900px 500px at 110% 0%, rgba(99, 102, 241, 0.08), transparent 60%),
    var(--bg);
  color: var(--text);
}

button, input, select { font: inherit; color: inherit; }

.app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 28px 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 16px;
}
.app-header h1 {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.tagline { margin: 4px 0 0; color: var(--text-muted); font-size: 0.9rem; }

/* Segmented controls */
.segmented {
  display: inline-flex;
  padding: 3px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
}
.segmented button {
  border: 0;
  background: transparent;
  padding: 6px 14px;
  border-radius: 999px;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 600;
}
.segmented button:hover { color: var(--text); }
.segmented button.is-selected { background: var(--surface-2); color: var(--text); box-shadow: 0 1px 0 rgba(255,255,255,0.05) inset, 0 1px 3px rgba(0,0,0,0.4); }
.segmented--small button { padding: 5px 10px; text-transform: uppercase; font-size: 0.75rem; letter-spacing: 0.04em; }

/* Toolbar */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  padding: 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.city-picker { position: relative; flex: 1 1 280px; max-width: 420px; }
.input {
  width: 100%;
  padding: 9px 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  outline: none;
}
.input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.15); }
.picker-list {
  position: absolute;
  z-index: 20;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  margin: 0;
  padding: 4px;
  list-style: none;
  max-height: 320px;
  overflow-y: auto;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}
.picker-item {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-radius: 6px;
  cursor: pointer;
}
.picker-item.is-active { background: rgba(52, 211, 153, 0.14); }
.picker-country { color: var(--text-muted); font-size: 0.85rem; }
.picker-empty { padding: 10px; color: var(--text-muted); }

.settings { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.field { display: flex; align-items: center; gap: 8px; font-size: 0.85rem; color: var(--text-muted); }
.field select {
  padding: 7px 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
}
.field-note { width: 100%; margin: 0; font-size: 0.8rem; color: var(--warn); }

/* Summary */
.summary {
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.summary-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.summary-count { font-weight: 700; font-size: 1.05rem; }
.summary-note { color: var(--text-muted); font-size: 0.85rem; }
.summary-empty { color: var(--text-muted); margin: 0; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(52, 211, 153, 0.14);
  border: 1px solid rgba(52, 211, 153, 0.35);
  color: #a7f3d0;
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
}
.warning {
  margin: 0;
  color: var(--warn);
  font-size: 0.9rem;
}
.base-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.base-item { padding: 10px 12px; background: var(--surface-2); border-radius: 8px; }
.base-title { display: flex; justify-content: space-between; margin-bottom: 6px; }
.base-name { font-weight: 600; }
.base-count { color: var(--text-muted); font-size: 0.85rem; }
.base-item .warning { font-size: 0.85rem; }

/* Badges + city header (shared) */
.badge {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--accent);
  color: var(--overlap-text);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  vertical-align: middle;
}
.city-header { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.city-title { display: flex; align-items: center; gap: 6px; min-width: 0; }
.city-name {
  padding: 0;
  border: 0;
  background: none;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.city-name:hover:not(:disabled) { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.city-name:disabled { cursor: default; }
.offset { color: var(--text-muted); font-size: 0.75rem; font-variant-numeric: tabular-nums; }
.remove-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
  opacity: 0.6;
}
.remove-btn:hover { opacity: 1; background: rgba(248, 113, 113, 0.15); color: #fca5a5; }

/* Desktop grid: one CSS grid, rows use display: contents so every row shares tracks */
.desktop-grid {
  display: grid;
  grid-template-columns: 190px repeat(24, minmax(38px, 1fr)) 34px;
  gap: 4px;
  padding: 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow-x: auto;
  min-width: 0;
}
.desktop-grid > * { min-width: 0; }
.dg-row { display: contents; }
.dg-corner, .dg-hour {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding-bottom: 6px;
  font-size: 0.7rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.dg-corner { justify-content: flex-start; font-size: 0.75rem; overflow: hidden; text-overflow: ellipsis; }
.dg-hour.is-overlap { color: var(--accent); font-weight: 700; }
.dg-info {
  position: relative;
  padding: 8px 30px 8px 10px;
  background: var(--surface-2);
  border-radius: 8px;
  display: flex;
  align-items: center;
}
.dg-info .city-header { flex-direction: column; }
.dg-info .remove-btn { display: none; }
.dg-spacer { }
.dg-row:hover .dg-info { background: #1b2a4b; }
.desktop-grid .dg-info > .city-header > .remove-btn { position: absolute; top: 50%; transform: translateY(-50%); right: 4px; }
.dg-cell {
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.dg-cell.is-asleep {
  background:
    repeating-linear-gradient(135deg, transparent 0 5px, rgba(255, 255, 255, 0.025) 5px 6px),
    var(--asleep-bg);
  color: var(--asleep-text);
}
.dg-cell.is-awake { background: var(--awake-bg); color: var(--awake-text); }
.dg-cell.is-overlap {
  background: linear-gradient(180deg, #5ee8b5, var(--accent-strong));
  color: var(--overlap-text);
  font-weight: 800;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.12) inset, 0 4px 14px rgba(16, 185, 129, 0.25);
}
.dg-spacer { width: 34px; }

/* Mobile grid: cities are columns, hours are rows */
.mobile-grid {
  display: grid;
  grid-template-columns: 74px repeat(var(--cols), minmax(112px, 1fr));
  gap: 4px;
  padding: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow-x: auto;
}
.mobile-grid > * { min-width: 0; }
.mg-hour-block { display: contents; }
.mg-corner {
  display: flex;
  align-items: flex-end;
  padding-bottom: 4px;
  font-size: 0.72rem;
  color: var(--text-muted);
}
.mg-head {
  position: relative;
  padding: 10px 26px 10px 10px;
  background: var(--surface-2);
  border-radius: 8px;
  margin-bottom: 4px;
}
.mg-head .remove-btn { top: 6px; right: 6px; }
.mg-time {
  display: flex;
  align-items: center;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.mg-time.is-overlap { color: var(--accent); font-weight: 700; }
.mg-cell {
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
}
.mg-cell.is-asleep {
  background:
    repeating-linear-gradient(135deg, transparent 0 5px, rgba(255, 255, 255, 0.025) 5px 6px),
    var(--asleep-bg);
  color: var(--asleep-text);
}
.mg-cell.is-awake { background: var(--awake-bg); color: var(--awake-text); }
