  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-radius: 6px;
  cursor: pointer;
}
.picker-item.is-active { background: rgba(52, 211, 153, 0.14); }
.picker-country { color: var(--text-muted); font-size: 0.85rem; }
.picker-empty { padding: 10px; color: var(--text-muted); }

.settings { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.field { display: flex; align-items: center; gap: 8px; font-size: 0.85rem; color: var(--text-muted); }
.field select {
  padding: 7px 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
