.badge {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--accent);
  color: var(--overlap-text);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  vertical-align: middle;
}
.city-header { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.city-title { display: flex; align-items: center; gap: 6px; min-width: 0; }
