.mobile-grid > * { min-width: 0; }
.mg-hour-block { display: contents; }
.mg-corner {
  display: flex;
  align-items: flex-end;
  padding-bottom: 4px;
  font-size: 0.72rem;
  color: var(--text-muted);
}
.mg-head {
  position: relative;
  padding: 10px 26px 10px 10px;
  background: var(--surface-2);
  border-radius: 8px;
  margin-bottom: 4px;
}
.mg-head .remove-btn { top: 6px; right: 6px; }
.mg-time {
  display: flex;
  align-items: center;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.mg-time.is-overlap { color: var(--accent); font-weight: 700; }
.mg-cell {
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
}
.mg-cell.is-asleep {
  background:
    repeating-linear-gradient(135deg, transparent 0 5px, rgba(255, 255, 255, 0.025) 5px 6px),
    var(--asleep-bg);
  color: var(--asleep-text);
}
.mg-cell.is-awake { background: var(--awake-bg); color: var(--awake-text); }
.mg-cell.is-overlap { background: linear-gradient(180deg, #5ee8b5, var(--accent-strong)); color: var(--overlap-text); font-weight: 800; }

/* Footer + empty */
.empty { text-align: center; color: var(--text-muted); padding: 40px 0; }
.hint {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.85rem;
  margin-top: 4px;
}
.hint::before {
  content: '';
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 8px;
  border-radius: 3px;
  background: var(--accent);
  vertical-align: -1px;
}

button:focus-visible, select:focus-visible, .segmented button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Desktop: the city info cell is a positioned container for the remove button */
@media (min-width: 768px) {
  .dg-info { padding-right: 30px; }
}

